def mom_gamma(xs):
    """Moment estimates (a_hat, lam_hat) of a Gamma, each rounded to 4 places."""
    n = len(xs)
    m = sum(xs) / n
    v = sum((x - m) ** 2 for x in xs) / n
    return (round(m * m / v, 4), round(m / v, 4))


def mom_uniform(xs):
    """Moment estimate of theta for a uniform on (0, theta)."""
    return 2 * sum(xs) / len(xs)


def mle_uniform(xs):
    """Maximum-likelihood estimate of theta for a uniform on (0, theta)."""
    return max(xs)
